package com.example.minicommerce.order.application;
import static com.example.minicommerce.order.api.OrderDtos.*;import com.example.minicommerce.audit.application.AuditService;import com.example.minicommerce.inventory.application.InventoryService;import com.example.minicommerce.messaging.application.OutboxService;import com.example.minicommerce.order.infrastructure.*;import com.example.minicommerce.promotion.application.CouponService;import com.example.minicommerce.shared.error.*;import com.example.minicommerce.shared.security.UserPrincipal;import java.time.Clock;import java.util.*;import java.util.stream.Collectors;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class OrderCommandService{private final OrderRepository orders;private final OrderItemRepository items;private final InventoryService inventory;private final CouponService coupons;private final OutboxService outbox;private final OrderQueryService query;private final AuditService audit;private final Clock clock;public OrderCommandService(OrderRepository o,OrderItemRepository i,InventoryService inv,CouponService c,OutboxService out,OrderQueryService q,AuditService a,Clock clock){orders=o;items=i;inventory=inv;coupons=c;outbox=out;query=q;audit=a;this.clock=clock;}@Transactional public OrderResponse cancel(UUID id,UserPrincipal actor){OrderEntity order=orders.findForUpdate(id).orElseThrow(()->new BusinessException(ErrorCode.ORDER_NOT_FOUND,"订单不存在"));query.authorize(order,actor);List<OrderItemEntity>lines=items.findByOrderIdOrderById(id);String before=order.getStatus().name();if(!order.cancel(clock.instant()))return OrderMapper.view(order,lines);Map<Long,Integer>qty=lines.stream().collect(Collectors.toMap(OrderItemEntity::getProductId,OrderItemEntity::getQuantity));inventory.release(qty);coupons.release(order.getUserCouponId(),id);outbox.append("ORDER",id.toString(),"order.cancelled.v1",Map.of("orderId",id,"userId",order.getUserId()));audit.record(actor.id(),"ORDER_CANCEL","ORDER",id,Map.of("status",before),Map.of("status",order.getStatus()));return OrderMapper.view(order,lines);}}
